import React, { createContext, useState } from 'react';


export const PetContext = createContext();


export const PetProvider = ({ children }) => {

  const [petsData, setPetsData] = useState([
    { id: 1, location: 'Germany', description: 'Permit to deliver things in Germany', age: 2, price: 100, img: '/assets/road.jpg' },
    { id: 2, location: 'France', description: 'Permit to deliver things in France', age: 5, price: 300, img: '/assets/road.jpg' },
    { id: 3, location: 'Italy', description: 'Permit to deliver things in Italy', age: 1, price: 50, img: '/assets/road.jpg' },
    { id: 4, location: 'Spain', description: 'Permit to deliver things in Spain', age: 13, price: 150, img: '/assets/road.jpg' },
    { id: 5, location: 'Belgium', description: 'Permit to deliver things in Belgium', age: 1, price: 325, img: '/assets/road.jpg' },
  ]);

  return (
    <PetContext.Provider value={{ petsData, setPetsData }}>
      {children}
    </PetContext.Provider>
  );
};
